using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;using System.ComponentModel;using System.Runtime.Serialization;using System.Globalization;
namespace CircuitoStudio {
[DataContract]public enum PoleLayout{[EnumMember] OnePole,[EnumMember] OnePoleNeutral,[EnumMember] TwoPole,[EnumMember] ThreePole,[EnumMember] ThreePoleNeutral,[EnumMember] FourPole}
[DataContract]public enum BreakingMetric{[EnumMember] Icu,[EnumMember] Icn}
[DataContract]public sealed class BreakerRating {
[DataMember]public string Manufacturer{get;set;}[DataMember]public string Reference{get;set;}[DataMember]public double VoltageV{get;set;}[DataMember]public double FrequencyHz{get;set;}[DataMember]public PoleLayout Poles{get;set;}[DataMember]public BreakingMetric Metric{get;set;}[DataMember]public double RatedA{get;set;}[DataMember]public double CapacityKA{get;set;}[DataMember]public double I2A{get;set;}[DataMember]public string Source{get;set;}[DataMember]public string DataVersion{get;set;}[DataMember]public string Standard{get;set;}[DataMember]public string Sheet{get;set;}
public BreakerRating(){Manufacturer=Reference=Source=DataVersion=Standard=Sheet="";}
public BreakerRating Copy(){return (BreakerRating)MemberwiseClone();}
public void Validate(){foreach(string value in new[]{Manufacturer,Reference,Source,DataVersion,Standard,Sheet})if(String.IsNullOrWhiteSpace(value)||value.Length>2000||value.IndexOf('\0')>=0)throw new InvalidDataException("Disjuntor exige fabricante, referência, fonte, versão, norma declarada e ficha (até 2000 caracteres).");Project.Range(VoltageV,1,1e6,"tensão ensaiada");Project.Range(FrequencyHz,1,1000,"frequência ensaiada");Project.Range(RatedA,.001,1e9,"In do disjuntor");Project.Range(CapacityKA,.001,1e9,"Icu/Icn");Project.Range(I2A,0,1e9,"I2 do disjuntor");if(!Enum.IsDefined(typeof(PoleLayout),Poles)||!Enum.IsDefined(typeof(BreakingMetric),Metric))throw new InvalidDataException("Polos ou classificação de interrupção inválidos.");}
public override string ToString(){return Manufacturer+" "+Reference+" / "+Poles+" / "+VoltageV+" V / "+Metric+"="+CapacityKA+" kA";}
}
[DataContract]public sealed class BreakerSnapshot {
[DataMember]public PoleLayout RequiredPoles{get;set;}[DataMember]public BreakingMetric RequiredMetric{get;set;}[DataMember]public BreakerRating Rating{get;set;}
public void Validate(){if(Rating==null||!Enum.IsDefined(typeof(PoleLayout),RequiredPoles)||!Enum.IsDefined(typeof(BreakingMetric),RequiredMetric))throw new InvalidDataException("Seleção do disjuntor incompleta.");Rating.Validate();}
}
public partial class ProtectionData{[DataMember,Browsable(false)]public BreakerSnapshot BreakerSnapshot{get;set;}}
public sealed class BreakerEvaluation {
[Browsable(false)]public BreakerRating Rating{get;set;}[DisplayName("Fabricante")]public string Manufacturer{get;set;}[DisplayName("Referência")]public string Reference{get;set;}[DisplayName("Polos")]public string Poles{get;set;}[DisplayName("Tensão (V)")]public double VoltageV{get;set;}[DisplayName("Classificação")]public string Metric{get;set;}[DisplayName("In (A)")]public double RatedA{get;set;}[DisplayName("Icu/Icn (kA)")]public double CapacityKA{get;set;}[DisplayName("Resultado")]public string Status{get;set;}[Browsable(false)]public string Detail{get;set;}
}
public static class BreakerSelection {
public const string Header="Manufacturer;Reference;VoltageV;FrequencyHz;Poles;Metric;RatedA;CapacityKA;I2A;Source;DataVersion;Standard;Sheet";
static string N(double x){return x.ToString("G8",CultureInfo.CurrentCulture);}static bool Equal(double a,double b){return Math.Abs(a-b)<=Math.Max(.001,Math.Abs(b)*1e-8);}
public static string PoleName(PoleLayout x){return new[]{"1P","1P+N","2P","3P","3P+N","4P"}[(int)x];}
internal static bool ValidTopology(CircuitResult circuit,PoleLayout poles){bool tri=poles==PoleLayout.ThreePole||poles==PoleLayout.ThreePoleNeutral||poles==PoleLayout.FourPole;bool neutral=poles==PoleLayout.OnePole||poles==PoleLayout.OnePoleNeutral;var c=circuit.Circuit;if(tri)return c.Phases==PhaseMode.Trifasico&&Equal(c.Voltage,circuit.Board.Voltage);if(c.Phases!=PhaseMode.Monofasico)return false;return neutral?Math.Abs(c.Voltage-circuit.Board.Voltage/Math.Sqrt(3))<=Math.Max(1,c.Voltage*.01)&&c.PhaseLabel!="ABC":Equal(c.Voltage,circuit.Board.Voltage);}
public static bool Applicable(Project project,CircuitResult circuit,BreakerSnapshot snapshot,out string detail){snapshot.Validate();var row=snapshot.Rating;bool pass=row.Poles==snapshot.RequiredPoles&&row.Metric==snapshot.RequiredMetric&&Equal(row.VoltageV,circuit.Circuit.Voltage)&&Equal(row.FrequencyHz,project.Frequency)&&ValidTopology(circuit,snapshot.RequiredPoles);detail="AC; configuração exigida "+PoleName(snapshot.RequiredPoles)+"; classificação "+snapshot.RequiredMetric+". Registro "+row.Manufacturer+" / "+row.Reference+", "+PoleName(row.Poles)+", "+row.VoltageV+" V, "+row.FrequencyHz+" Hz, In="+row.RatedA+" A; "+row.Metric+"="+row.CapacityKA+" kA; norma declarada "+row.Standard+". Fonte: "+row.Source+"; versão "+row.DataVersion+"; ficha "+row.Sheet+". "+(pass?"Condições coincidem.":"Condição incompatível: tensão, frequência, polos, classificação ou ligação/fases do circuito.")+" Sem extrapolação entre tensões, polos ou classificações; conferir ambiente, instalação, seletividade e coordenação.";return pass;}
public static BreakerEvaluation Evaluate(Project project,CircuitResult circuit,BreakerRating row,PoleLayout requiredPoles,BreakingMetric requiredMetric){if(project==null||circuit==null||row==null)throw new InvalidDataException("Dados de comparação ausentes.");string detail;bool compatible=Applicable(project,circuit,new BreakerSnapshot{Rating=row,RequiredPoles=requiredPoles,RequiredMetric=requiredMetric},out detail);bool fail=!compatible;var text=new StringBuilder(detail);bool pending=false;Compare(text,"Ib ≤ In",circuit.CurrentA<=row.RatedA,"Ib="+N(circuit.CurrentA)+" A; In="+N(row.RatedA)+" A",ref fail,ref pending);Compare(text,"In ≤ Iz",circuit.CorrectedAmpacityA.HasValue?(bool?)(row.RatedA<=circuit.CorrectedAmpacityA.Value):null,"Iz="+(circuit.CorrectedAmpacityA.HasValue?N(circuit.CorrectedAmpacityA.Value):"pendente")+" A",ref fail,ref pending);Compare(text,"I2 ≤ 1,45 Iz",row.I2A>0&&circuit.CorrectedAmpacityA.HasValue?(bool?)(row.I2A<=1.45*circuit.CorrectedAmpacityA.Value):null,"I2="+N(row.I2A)+" A",ref fail,ref pending);Compare(text,row.Metric+" ≥ Ik na origem",compatible&&circuit.FaultOriginKA.HasValue?(bool?)(row.CapacityKA>=circuit.FaultOriginKA.Value):null,"Ik 3F nominal aproximado="+(circuit.FaultOriginKA.HasValue?N(circuit.FaultOriginKA.Value):"pendente")+" kA",ref fail,ref pending);text.Append(" A comparação usa o curto nominal disponível, sem comprovação de Ik máximo normativo, contribuição de motores, backup/cascata ou aprovação global.");return new BreakerEvaluation{Rating=row,Manufacturer=row.Manufacturer,Reference=row.Reference,Poles=PoleName(row.Poles),VoltageV=row.VoltageV,Metric=row.Metric.ToString(),RatedA=row.RatedA,CapacityKA=row.CapacityKA,Status=fail?"Não atende":pending?"Dados incompletos":"Atende comparações nominais",Detail=text.ToString()};}
static void Compare(StringBuilder text,string rule,bool? pass,string detail,ref bool fail,ref bool pending){if(!pass.HasValue)pending=true;else if(!pass.Value)fail=true;text.Append("\r\n"+(pass.HasValue?(pass.Value?"Atende":"Não atende"):"Pendente")+": "+rule+"; "+detail+".");}
public static void Apply(Project project,Circuit circuit,BreakerRating row,PoleLayout poles,BreakingMetric metric){ApplyInternal(project,circuit,row,poles,metric,false);}
public static void ApplyForCoordinationStudy(Project project,Circuit circuit,BreakerRating row,PoleLayout poles,BreakingMetric metric){ApplyInternal(project,circuit,row,poles,metric,true);}
static void ApplyInternal(Project project,Circuit circuit,BreakerRating row,PoleLayout poles,BreakingMetric metric,bool coordinationStudy){var study=Engineering.Analyze(project);var context=study.For(circuit);if(context==null)throw new InvalidDataException("Circuito ausente do projeto.");var evaluation=Evaluate(project,context,row,poles,metric);string conditionDetail;bool eligibleForStudy=coordinationStudy&&Applicable(project,context,new BreakerSnapshot{Rating=row,RequiredPoles=poles,RequiredMetric=metric},out conditionDetail)&&context.CurrentA<=row.RatedA&&(!context.CorrectedAmpacityA.HasValue||(row.RatedA<=context.CorrectedAmpacityA.Value&&(row.I2A==0||row.I2A<=1.45*context.CorrectedAmpacityA.Value)));if(evaluation.Status=="Não atende"&&!eligibleForStudy)throw new InvalidDataException("Nenhuma alteração: o disjuntor não atende à comparação. "+evaluation.Detail);circuit.Protection.BreakerSnapshot=new BreakerSnapshot{Rating=row.Copy(),RequiredPoles=poles,RequiredMetric=metric};circuit.BreakerA=row.RatedA;circuit.Protection.BreakingCapacityKA=row.CapacityKA;circuit.Protection.ConventionalTripA=row.I2A;
// A new device must not inherit curves, energy or trip times from the previous device.
circuit.Protection.LetThroughA2s=0;circuit.Protection.MagneticTripA=0;circuit.Protection.DisconnectSeconds=0;circuit.Protection.RcdMilliA=0;if(circuit.CurveStudy!=null)circuit.CurveStudy.Downstream=null;}
public static void Validate(Circuit circuit){var snapshot=circuit.Protection.BreakerSnapshot;if(snapshot==null)return;snapshot.Validate();if(circuit.BreakerA!=snapshot.Rating.RatedA||circuit.Protection.BreakingCapacityKA!=snapshot.Rating.CapacityKA||circuit.Protection.ConventionalTripA!=snapshot.Rating.I2A)throw new InvalidDataException("Valores manuais contradizem o disjuntor vinculado. Reaplique a seleção ou remova o vínculo.");}
static double Number(string text){double value;if(text.Contains('.')&&text.Contains(','))throw new InvalidDataException("Número ambíguo.");if(!double.TryParse(text.Trim().Replace(',','.'),NumberStyles.Float,CultureInfo.InvariantCulture,out value)||double.IsNaN(value)||double.IsInfinity(value))throw new InvalidDataException("Número inválido.");return value;}
static T EnumValue<T>(string text){try{var value=(T)Enum.Parse(typeof(T),text,true);if(Enum.IsDefined(typeof(T),value))return value;}catch{}throw new InvalidDataException("Polos/classificação inválidos.");}
static void ValidateRows(List<BreakerRating> rows){if(rows.Count>100000)throw new InvalidDataException("Tabela excede 100000 itens.");var keys=new HashSet<string>(StringComparer.OrdinalIgnoreCase);foreach(var row in rows){if(row==null)throw new InvalidDataException("Linha ausente.");row.Validate();string key=String.Join("\0",new[]{row.Manufacturer.Trim(),row.Reference.Trim(),row.VoltageV.ToString("R",CultureInfo.InvariantCulture),row.FrequencyHz.ToString("R",CultureInfo.InvariantCulture),row.Poles.ToString(),row.Metric.ToString()});if(!keys.Add(key))throw new InvalidDataException("Condição de disjuntor duplicada.");}}
public static List<BreakerRating> Import(string file){if(new FileInfo(file).Length>32L*1024*1024)throw new InvalidDataException("Tabela excede 32 MiB.");var rows=CatalogData.Rows(File.ReadAllText(file,Encoding.UTF8).TrimStart('\uFEFF'));if(rows.Count==0||rows.Count>100001||String.Join(";",rows[0])!=Header)throw new InvalidDataException("Cabeçalho/tamanho incompatível.");var values=new List<BreakerRating>();for(int i=1;i<rows.Count;i++){try{var x=rows[i];if(x.Length!=13)throw new InvalidDataException("Esperadas 13 colunas.");values.Add(new BreakerRating{Manufacturer=x[0],Reference=x[1],VoltageV=Number(x[2]),FrequencyHz=Number(x[3]),Poles=EnumValue<PoleLayout>(x[4]),Metric=EnumValue<BreakingMetric>(x[5]),RatedA=Number(x[6]),CapacityKA=Number(x[7]),I2A=Number(x[8]),Source=x[9],DataVersion=x[10],Standard=x[11],Sheet=x[12]});}catch(Exception ex){throw new InvalidDataException("Registro "+(i+1)+": "+ex.Message,ex);}}ValidateRows(values);return values;}
static string Quote(string s){return "\""+s.Replace("\"","\"\"")+"\"";}
public static void Export(IEnumerable<BreakerRating> rows,string file){var list=rows.ToList();ValidateRows(list);string full=Path.GetFullPath(file);Directory.CreateDirectory(Path.GetDirectoryName(full));string temp=full+"."+Guid.NewGuid().ToString("N")+".tmp";try{long bytes=3+Encoding.UTF8.GetByteCount(Header+"\r\n");using(var w=new StreamWriter(temp,false,new UTF8Encoding(true))){w.WriteLine(Header);foreach(var r in list){var fields=new[]{r.Manufacturer,r.Reference,r.VoltageV.ToString("R",CultureInfo.InvariantCulture),r.FrequencyHz.ToString("R",CultureInfo.InvariantCulture),r.Poles.ToString(),r.Metric.ToString(),r.RatedA.ToString("R",CultureInfo.InvariantCulture),r.CapacityKA.ToString("R",CultureInfo.InvariantCulture),r.I2A.ToString("R",CultureInfo.InvariantCulture),r.Source,r.DataVersion,r.Standard,r.Sheet};string line=String.Join(";",fields.Select(Quote));bytes+=Encoding.UTF8.GetByteCount(line+"\r\n");if(bytes>32L*1024*1024)throw new InvalidDataException("Tabela excede 32 MiB; destino preservado.");w.WriteLine(line);}}if(File.Exists(full))File.Replace(temp,full,full+".bak");else File.Move(temp,full);}finally{if(File.Exists(temp))File.Delete(temp);}}
}
}
